import { Check, Luggage, Sun } from 'lucide-react';
import { Card, Typography } from '@/components';

export type PackingCategory = 'clothing' | 'documents' | 'health' | 'electronics' | 'other';

export interface PackingChecklistItem {
  category: PackingCategory;
  label: string;
  essential: boolean;
}

export interface PackingChecklistCardProps {
  destination: string;
  tripDays: number;
  weatherNote: string;
  items: PackingChecklistItem[];
}

/** A render-only packing checklist generated by the travel agent. */
export const PackingChecklistCard = ({
  destination,
  tripDays,
  weatherNote,
  items,
}: PackingChecklistCardProps) => (
  <Card className="w-full max-w-2xl shadow" paddingClass="p-0">
    <div className="bg-user-gradient px-5 py-3 text-white">
      <div className="flex items-center gap-2">
        <Luggage size={16} aria-hidden="true" className="text-white/70" />
        <Typography variant="card-title" weight="medium" className="text-white">
          Packing for {destination}
        </Typography>
      </div>
      <Typography variant="meta" className="mt-0.5 text-white/70">
        {tripDays} day{tripDays === 1 ? '' : 's'} away
      </Typography>
    </div>
    <div className="space-y-3 px-5 py-4">
      <div className="bg-background-info text-text-secondary flex items-center gap-2 rounded-md px-3 py-2">
        <Sun size={14} aria-hidden="true" />
        <Typography variant="meta" color="secondary">
          {weatherNote}
        </Typography>
      </div>
      <ul className="space-y-2" aria-label="Packing checklist">
        {items.map((item) => (
          <li key={`${item.category}-${item.label}`} className="flex items-center gap-2">
            <Check size={15} aria-hidden="true" className="text-badge-success-text" />
            <Typography variant="body">{item.label}</Typography>
            {item.essential && (
              <span className="bg-badge-warning-bg text-badge-warning-text text-badge rounded-full px-2 py-0.5 font-medium">
                Essential
              </span>
            )}
          </li>
        ))}
      </ul>
    </div>
  </Card>
);
